package cinema.util;

import org.mindrot.jbcrypt.BCrypt;

/**
 * BCrypt-based password hashing (cost factor 12).
 *
 * DEMO NOTE: The two seed accounts (admin / student) in the SQL script use
 * SHA-256 hashes generated by MySQL's SHA2().  When those users log in for the
 * first time the app detects the old hash format (no "$2a$" prefix) and accepts
 * SHA-256 for that login only.  New registrations always use BCrypt.
 */
public class PasswordUtil {

    private static final int BCRYPT_ROUNDS = 12;

    /** Hash a plain-text password with BCrypt. */
    public static String hash(String password) {
        return BCrypt.hashpw(password, BCrypt.gensalt(BCRYPT_ROUNDS));
    }

    /**
     * Verify a plain-text password against a stored hash.
     * Accepts both BCrypt (new) and SHA-256 hex (legacy seed accounts).
     */
    public static boolean matches(String plainPassword, String storedHash) {
        if (plainPassword == null || storedHash == null) return false;

        // BCrypt hashes start with $2a$, $2b$, or $2y$
        if (storedHash.startsWith("$2")) {
            return BCrypt.checkpw(plainPassword, storedHash);
        }

        // Legacy SHA-256 fallback for seed accounts
        return sha256Hex(plainPassword).equalsIgnoreCase(storedHash);
    }

    // ── SHA-256 fallback ──────────────────────────────────────────────────────
    private static String sha256Hex(String input) {
        try {
            java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
            byte[] bytes = md.digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : bytes) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("SHA-256 not available.", e);
        }
    }
}
